function mk_h($v): string { return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function mk_json($v): string { return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR); }
function mk_shop_catalog(): array { static $c; return $c??=json_decode(file_get_contents(dirname(__DIR__).'/content/shop-catalog.json'),true,512,JSON_THROW_ON_ERROR); }
function mk_link(string $path): string { return 'https://meinkraut.odpc.de'.$path; }
function mk_cards(array $items,callable $url): string { $s='<div class="mk-grid">';foreach($items as $r){$s.='<article class="mk-card"><h2><a href="'.mk_h($url($r)).'">'.mk_h($r['name']).'</a></h2><p>'.mk_h($r['description']??$r['usage']??$r['flavor']??'').'</p></article>'; }return $s.'</div>'; }
function mk_sources(array $sources): string { $out='';foreach($sources as $s){if(!empty($s['url'])&&preg_match('~^https://~',$s['url']))$out.='<li><a href="'.mk_h($s['url']).'" rel="noopener noreferrer">'.mk_h($s['title']??$s['url']).'</a></li>'; }return $out?'<details><summary>Quellen und Einordnung</summary><ul>'.$out.'</ul></details>':''; }
